DESCRIBE smartcart.`smartcart(orders)`;

-- Business Question:
-- What is the total revenue generated by SmartCart in USD?

SELECT
    ROUND(SUM(order_total_usd), 2) AS total_revenue_usd
FROM smartcart.`smartcart(orders)`;

-- Business Question:
-- How many orders were placed, and what was the average order value in USD?

SELECT
    COUNT(order_id) AS total_orders,
    ROUND(AVG(order_total_usd), 2) AS average_order_value_usd
FROM smartcart.`smartcart(orders)`;

-- Business Question:
-- What is the distribution of orders by order status?

SELECT
    order_status,
    COUNT(order_id) AS total_orders,
    ROUND(
        COUNT(order_id) * 100.0 /
        (SELECT COUNT(*) FROM smartcart.`smartcart(orders)`),
        2
    ) AS order_percentage
FROM smartcart.`smartcart(orders)`
GROUP BY order_status
ORDER BY total_orders DESC;

-- Business Question:
-- How much revenue is associated with each order status?

SELECT
    order_status,
    COUNT(order_id) AS total_orders,
    ROUND(SUM(order_total_usd), 2) AS total_revenue_usd,
    ROUND(AVG(order_total_usd), 2) AS average_order_value_usd
FROM smartcart.`smartcart(orders)`
GROUP BY order_status
ORDER BY total_revenue_usd DESC;

-- Business Question:
-- What are the monthly order volumes and revenue trends?

SELECT
    order_month,
    COUNT(order_id) AS total_orders,
    ROUND(SUM(order_total_usd), 2) AS total_revenue_usd
FROM smartcart.`smartcart(orders)`
GROUP BY order_month
ORDER BY order_month;

-- Business Question:
-- How do yearly order volume and revenue compare?

SELECT
    LEFT(order_month, 4) AS sales_year,
    COUNT(order_id) AS total_orders,
    ROUND(SUM(order_total_usd), 2) AS total_revenue_usd,
    ROUND(AVG(order_total_usd), 2) AS average_order_value_usd
FROM smartcart.`smartcart(orders)`
GROUP BY LEFT(order_month, 4)
ORDER BY sales_year;

-- Business Question:
-- Which sales channels generate the most orders and revenue?

SELECT
    sales_channel,
    COUNT(order_id) AS total_orders,
    ROUND(SUM(order_total_usd), 2) AS total_revenue_usd,
    ROUND(AVG(order_total_usd), 2) AS average_order_value_usd
FROM smartcart.`smartcart(orders)`
GROUP BY sales_channel
ORDER BY total_revenue_usd DESC;

-- Business Question:
-- How do order volume and revenue vary by device type?

SELECT
    device_type,
    COUNT(order_id) AS total_orders,
    ROUND(SUM(order_total_usd), 2) AS total_revenue_usd,
    ROUND(AVG(order_total_usd), 2) AS average_order_value_usd
FROM smartcart.`smartcart(orders)`
GROUP BY device_type
ORDER BY total_revenue_usd DESC;

-- Business Question:
-- How do order volume and revenue vary by payment method?

SELECT
    payment_method,
    COUNT(order_id) AS total_orders,
    ROUND(SUM(order_total_usd), 2) AS total_revenue_usd,
    ROUND(AVG(order_total_usd), 2) AS average_order_value_usd
FROM smartcart.`smartcart(orders)`
GROUP BY payment_method
ORDER BY total_orders DESC;

-- Business Question:
-- Which countries generate the highest order volume and revenue?

SELECT
    shipping_country,
    COUNT(order_id) AS total_orders,
    ROUND(SUM(order_total_usd), 2) AS total_revenue_usd,
    ROUND(AVG(order_total_usd), 2) AS average_order_value_usd
FROM smartcart.`smartcart(orders)`
GROUP BY shipping_country
ORDER BY total_revenue_usd DESC;

-- Business Question:
-- Which shipping regions generate the highest order volume and revenue?

SELECT
    shipping_region,
    COUNT(order_id) AS total_orders,
    ROUND(SUM(order_total_usd), 2) AS total_revenue_usd,
    ROUND(AVG(order_total_usd), 2) AS average_order_value_usd
FROM smartcart.`smartcart(orders)`
GROUP BY shipping_region
ORDER BY total_revenue_usd DESC;